class Thermostat {
    private int temp;
    Thermostat(int start) { temp = clamp(start); }
    int set(int n) { temp = clamp(n); return temp; }
    int up() { temp = clamp(temp + 1); return temp; }
    int down() { temp = clamp(temp - 1); return temp; }
    private int clamp(int n) { return Math.max(60, Math.min(85, n)); }
}

class Solution {
    public static String run(String commands) {
        if (commands.isEmpty()) return "";
        Thermostat t = new Thermostat(70);
        String[] lines = commands.split("\n");
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < lines.length; i++) {
            String line = lines[i].trim();
            int result;
            if (line.startsWith("SET")) {
                result = t.set(Integer.parseInt(line.substring(4).trim()));
            } else if (line.equals("UP")) {
                result = t.up();
            } else {
                result = t.down();
            }
            if (i > 0) out.append("\n");
            out.append(result);
        }
        return out.toString();
    }
}

