class Song {
    String title;
    int seconds;
    Song(String title, int seconds) {
        this.title = title;
        this.seconds = seconds;
    }
}

class Playlist {
    private List<Song> songs = new ArrayList<>();
    void add(Song s) {
        songs.add(s);
    }
    int totalSeconds() {
        int total = 0;
        for (Song s : songs) total += s.seconds;
        return total;
    }
}

class Solution {
    public static String totalTime(String[] titles, int[] seconds) {
        Playlist playlist = new Playlist();
        for (int i = 0; i < titles.length; i++) {
            playlist.add(new Song(titles[i], seconds[i]));
        }
        int total = playlist.totalSeconds();
        int m = total / 60;
        int s = total % 60;
        return m + ":" + String.format("%02d", s);
    }
}

