abstract class Employee {
    String name;
    double baseSalary;
    Employee(String name, double baseSalary) {
        this.name = name;
        this.baseSalary = baseSalary;
    }
    abstract double bonus();
}

class Manager extends Employee {
    Manager(String name, double baseSalary) {
        super(name, baseSalary);
    }
    double bonus() {
        return baseSalary * 0.20 + 500;
    }
}

class Developer extends Employee {
    int projects;
    Developer(String name, double baseSalary, int projects) {
        super(name, baseSalary);
        this.projects = projects;
    }
    double bonus() {
        return baseSalary * 0.10 + projects * 50;
    }
}

class Intern extends Employee {
    Intern(String name, double baseSalary) {
        super(name, baseSalary);
    }
    double bonus() {
        return 100;
    }
}

class Solution {
    public static String totalBonus(String[] roles, String[] names, double[] baseSalaries, int[] extra) {
        double total = 0;
        for (int i = 0; i < roles.length; i++) {
            Employee e;
            switch (roles[i]) {
                case "manager": e = new Manager(names[i], baseSalaries[i]); break;
                case "developer": e = new Developer(names[i], baseSalaries[i], extra[i]); break;
                case "intern": e = new Intern(names[i], baseSalaries[i]); break;
                default: e = null;
            }
            if (e != null) total += e.bonus();
        }
        return String.format(java.util.Locale.US, "%.2f", total);
    }
}

