public class Solution {
    private static void validate(boolean membershipActive, int copiesAvailable, int booksAlreadyOut)
            throws InactiveMembershipException, OutOfStockException, LimitReachedException {
        if (!membershipActive) throw new InactiveMembershipException("inactive membership");
        if (copiesAvailable <= 0) throw new OutOfStockException("no copies available");
        if (booksAlreadyOut >= 3) throw new LimitReachedException("limit reached");
    }
    public static String checkout(boolean membershipActive, int copiesAvailable, int booksAlreadyOut) {
        try {
            validate(membershipActive, copiesAvailable, booksAlreadyOut);
            return "approved";
        } catch (InactiveMembershipException | OutOfStockException | LimitReachedException e) {
            return e.getMessage();
        }
    }
}

