import java.util.*;

class TicketCounter {
    private static TicketCounter instance;
    private int issued = 0;
    private TicketCounter() {}
    static TicketCounter getInstance() {
        if (instance == null) instance = new TicketCounter();
        return instance;
    }
    int next() { issued += 1; return issued; }
    int total() { return issued; }
}
public class Solution {
    public static String process(String[] commands) {
        List<String> out = new ArrayList<>();
        for (String line : commands) {
            String[] parts = line.trim().split(" ", 2);
            String cmd = parts[0];
            if (cmd.equals("NEW")) {
                String dept = parts[1];
                int num = TicketCounter.getInstance().next();
                out.add(dept + ":" + num);
            } else if (cmd.equals("COUNT")) {
                out.add("count:" + TicketCounter.getInstance().total());
            }
        }
        return String.join(",", out);
    }
}

