            if (codes[i].equals("goblin")) spawner = new GoblinSpawner();
            else if (codes[i].equals("dragon")) spawner = new DragonSpawner();
            else spawner = null;
            if (i > 0) sb.append(",");
            sb.append(spawner == null ? "unknown" : spawner.spawn(level));
        }
        return sb.toString();
    }
}

