class Solution {
    public static String finalPrice(double basePrice, boolean memberDiscount, int extraShots) {
        double total = basePrice + extraShots * 0.75;
        if (memberDiscount) {
            total = total * 0.90;
        }
        if (total > 6.00) {
            total += 0.30;
        }
        return "$" + String.format(java.util.Locale.US, "%.2f", total);
    }
